html:
{% set garage_name = frappe.db.get_single_value("Garage Branding Settings", "garage_name") or "SubaMaz" %}
{% set tagline = frappe.db.get_single_value("Garage Branding Settings", "tagline") %}
{% set motto = frappe.db.get_single_value("Garage Branding Settings", "motto") %}
{% set logo = frappe.db.get_single_value("Garage Branding Settings", "logo") %}
{% set primary = frappe.db.get_single_value("Theme", "primary_color") or "#434868" %}
{% set accent = frappe.db.get_single_value("Theme", "accent_color") or "#C9A227" %}
{% set address = frappe.db.get_single_value("Garage Branding Settings", "address") %}
{% set phone = frappe.db.get_single_value("Garage Branding Settings", "phone") %}
{% set email = frappe.db.get_single_value("Garage Branding Settings", "email") %}
{% set abbr = garage_name[:2].upper() if garage_name else "GM" %}
<div style="padding:16px;font-family:Inter, sans-serif;font-size:11px;color:#1a1a1a">
<div style="border-bottom:3px solid {{ accent }};padding-bottom:10px;display:flex;justify-content:space-between;align-items:center;margin-bottom:14px">
<div style="display:flex;gap:10px;align-items:center">
{% if logo %}<img src="{{ logo }}" style="width:44px;height:44px;object-fit:contain;border-radius:8px;border:1px solid #eee">
{% else %}<div style="width:44px;height:44px;background:{{ primary }};color:#fff;display:flex;align-items:center;justify-content:center;border-radius:8px;font-weight:700;font-size:13px">{{ abbr }}</div>{% endif %}
<div>
<div style="font-weight:700;font-size:15px">{{ garage_name }}</div>
{% if tagline %}<div style="font-size:9px;color:#666">{{ tagline }}</div>{% endif %}
</div>
</div>
<div style="text-align:right;font-size:9px;color:#555;line-height:1.4">
{% if address %}<div>{{ address }}</div>{% endif %}
{% if phone %}<div>Tel: {{ phone }}</div>{% endif %}
{% if email %}<div>{{ email }}</div>{% endif %}
</div>
</div><h2 style="font-size:16px;margin:0 0 8px">Delivery Note — {{ doc.name }}</h2>
<p style="margin:0 0 6px"><strong>Vehicle:</strong> {{ doc.vehicle }} &nbsp; <strong>Customer:</strong> {{ doc.customer }}</p>
<p style="margin:0 0 10px"><strong>Service Order:</strong> {{ doc.service_order }} &nbsp; <strong>Date:</strong> {{ doc.delivery_date }}</p>
<h3 style="font-size:12px;margin:12px 0 6px;border-bottom:1px solid #eee;padding-bottom:4px">Checklist</h3>
<table style="width:100%;border-collapse:collapse;font-size:10px"><thead><tr style="background:#f8f7f3"><th style="padding:4px;border:1px solid #ddd">Item</th><th style="padding:4px;border:1px solid #ddd;width:60px">Done</th></tr></thead><tbody>{% for row in doc.checklist %}<tr><td style="padding:4px;border:1px solid #ddd">{{ row.checklist_item }}</td><td style="padding:4px;border:1px solid #ddd">{{ 'Yes' if row.completed else 'No' }}</td></tr>{% endfor %}</tbody></table>
<h3 style="font-size:12px;margin:12px 0 6px">Photos</h3>{% for row in doc.photos %}<div style="margin-bottom:6px"><img src="{{ row.photo }}" style="max-width:180px;border-radius:6px"/> <span style="font-size:9px;color:#666">{{ row.photo_type }}</span></div>{% endfor %}
<div style="margin-top:28px;display:flex;justify-content:space-between;font-size:10px;border-top:1px solid #eee;padding-top:10px"><div>Customer Signature: ______________________</div><div>Staff Signature: ______________________</div></div><div style="text-align:center;font-size:8px;color:#888;margin-top:10px;border-top:1px solid #f0f0f0;padding-top:6px">{{ motto or "Expert care for every vehicle we serve" }}</div>
</div>

{% set garage_name = frappe.db.get_single_value("Garage Branding Settings", "garage_name") or "SubaMaz" %}
{% set tagline = frappe.db.get_single_value("Garage Branding Settings", "tagline") %}
{% set motto = frappe.db.get_single_value("Garage Branding Settings", "motto") %}
{% set logo = frappe.db.get_single_value("Garage Branding Settings", "logo") %}
{% set primary = frappe.db.get_single_value("Theme", "primary_color") or "#434868" %}
{% set accent = frappe.db.get_single_value("Theme", "accent_color") or "#C9A227" %}
{% set address = frappe.db.get_single_value("Garage Branding Settings", "address") %}
{% set phone = frappe.db.get_single_value("Garage Branding Settings", "phone") %}
{% set email = frappe.db.get_single_value("Garage Branding Settings", "email") %}
{% set abbr = garage_name[:2].upper() if garage_name else "GM" %}
<div style="padding:16px;font-family:Inter, sans-serif;font-size:11px;color:#1a1a1a">
<div style="border-bottom:3px solid {{ accent }};padding-bottom:10px;display:flex;justify-content:space-between;align-items:center;margin-bottom:14px">
<div style="display:flex;gap:10px;align-items:center">
{% if logo %}<img src="{{ logo }}" style="width:44px;height:44px;object-fit:contain;border-radius:8px;border:1px solid #eee">
{% else %}<div style="width:44px;height:44px;background:{{ primary }};color:#fff;display:flex;align-items:center;justify-content:center;border-radius:8px;font-weight:700;font-size:13px">{{ abbr }}</div>{% endif %}
<div>
<div style="font-weight:700;font-size:15px">{{ garage_name }}</div>
{% if tagline %}<div style="font-size:9px;color:#666">{{ tagline }}</div>{% endif %}
</div>
</div>
<div style="text-align:right;font-size:9px;color:#555;line-height:1.4">
{% if address %}<div>{{ address }}</div>{% endif %}
{% if phone %}<div>Tel: {{ phone }}</div>{% endif %}
{% if email %}<div>{{ email }}</div>{% endif %}
</div>
</div><h2 style="font-size:16px;border-bottom:2px solid {{ primary }};padding-bottom:6px">Vehicle Inspection Report — {{ doc.name }}</h2>
<p style="margin:6px 0"><strong>Vehicle:</strong> {{ doc.vehicle }} &nbsp; <strong>Customer:</strong> {{ doc.customer or '' }} &nbsp; <strong>Date:</strong> {{ doc.inspection_date or '' }}</p>
<p style="margin:0 0 10px"><strong>Inspector:</strong> {{ doc.inspector or '' }} &nbsp; <strong>Type:</strong> {{ doc.inspection_type or '' }} &nbsp; <strong>Mileage:</strong> {{ doc.mileage or '' }}</p>
<table style="width:100%;border-collapse:collapse;font-size:10px"><thead><tr style="background:#f8f7f3"><th style="padding:4px;border:1px solid #ddd">Section</th><th style="padding:4px;border:1px solid #ddd">Item</th><th style="padding:4px;border:1px solid #ddd">Result</th><th style="padding:4px;border:1px solid #ddd">Notes</th></tr></thead><tbody>{% for row in doc.checklist %}<tr><td style="padding:4px;border:1px solid #ddd">{{ row.section }}</td><td style="padding:4px;border:1px solid #ddd">{{ row.checklist_item }}</td><td style="padding:4px;border:1px solid #ddd">{{ row.result }}</td><td style="padding:4px;border:1px solid #ddd">{{ row.notes or '' }}</td></tr>{% endfor %}</tbody></table>
<p style="margin-top:12px"><strong>Result:</strong> <span style="font-size:13px;font-weight:700;color:{{ primary }}">{{ doc.inspection_result or 'N/A' }}</span> &nbsp; <strong>Recommendation:</strong> {{ doc.recommendation or 'N/A' }}</p>
{% if doc.notes %}<div style="background:#f9f9f7;border:1px solid #eee;border-radius:8px;padding:8px;margin-top:8px"><strong>Notes:</strong> {{ doc.notes }}</div>{% endif %}
<div style="margin-top:28px;display:flex;justify-content:space-between;font-size:10px;border-top:1px solid #eee;padding-top:10px"><div>Inspector Signature: ______________________</div><div>Date: {{ doc.inspection_date or '' }}</div></div>
<div style="text-align:center;font-size:8px;color:#888;margin-top:10px">{{ motto or "Expert care for every vehicle we serve" }}</div>
</div>
